package com.shipflow.order;
import com.shipflow.order.api.model.*;import com.shipflow.order.application.*;import com.shipflow.order.domain.model.ShipmentOrder;import com.shipflow.order.mapper.ShipmentOrderMapper;import org.junit.jupiter.api.Test;import java.math.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class ShipmentOrderLifecycleApplicationServiceTest {ShipmentOrderMapper m=mock(ShipmentOrderMapper.class);ShipmentOrderQueryApplicationService q=new ShipmentOrderQueryApplicationService(m);ShipmentOrderLifecycleApplicationService s=new ShipmentOrderLifecycleApplicationService(m,q,Clock.fixed(Instant.EPOCH,ZoneOffset.UTC));ShipmentOrder o(String status){return new ShipmentOrder(1L,7L,"SO","k",3L,9L,4L,status,"CN","US",BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.TEN,"USD",LocalDateTime.of(2026,1,1,0,0));}@Test void submitsOnlyDraftWithVersion(){when(m.findById(7L,1L)).thenReturn(o("DRAFT"),o("PENDING_INBOUND"));when(m.transitionStatus(7L,1L,"DRAFT","PENDING_INBOUND",0L)).thenReturn(1);assertThat(s.submit(7L,2L,1L,new OrderActionRequest(0L,null),"r").status()).isEqualTo("PENDING_INBOUND");verify(m).insertAuditAction(7L,2L,1L,"SUBMIT","r","SUCCESS",null,LocalDateTime.of(1970,1,1,0,0));}@Test void rejectsBillingChangeInDraft(){when(m.findById(7L,1L)).thenReturn(o("DRAFT"));var a=new CreateShipmentOrderRequest.Address("a","p",null,null,"CN",null,"c",null,"l",null,"z");var r=new UpdateShipmentOrderRequest(0L,a,a,List.<CreateShipmentOrderRequest.Item>of(),null,null,null,BigDecimal.ONE,null,null,null,null,null,null,null,null,null);assertThatThrownBy(()->s.updateDraft(7L,2L,1L,r,"r")).isInstanceOf(ShipmentOrderException.class).satisfies(e->assertThat(((ShipmentOrderException)e).code()).isEqualTo("ORDER-1007"));}}
